package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen2Test {

    @Test
    public void testValue_withNull() throws IOException {
        StringWriter writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);

        // The method returns nullValue() when value is null.
        // Based on the provided code: if (value == null) return nullValue();
        // We need to verify if the return value is the result of nullValue()
        // and if the output is "null".
        JsonWriter result = jsonWriter.value((String) null);

        assertEquals("null", writer.toString());
        // Since nullValue() returns this (the JsonWriter instance), result should be jsonWriter
        assertSame(jsonWriter, result);
    }






}

package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen2Test {



    @Test
    public void testValue_withString() throws IOException {
        StringWriter writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);

        // Prepare the writer state for a value (needs to be in an object or array context)
        jsonWriter.beginObject();
        jsonWriter.name("testKey");

        String testValue = "Hello World";
        JsonWriter result = jsonWriter.value(testValue);

        // The output should be "testKey":"Hello World"
        // After value(), we close the object to finish the JSON
        jsonWriter.endObject();

        String expected = "{\"testKey\":\"Hello World\"}";
        assertEquals(expected, writer.toString());

        // The method returns 'this'
        assertSame(jsonWriter, result);
    }




}

