package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen2Test {







    @Test
    public void testValue_withSpecialCharacters() throws IOException {
        StringWriter writer = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(writer);

        jsonWriter.beginArray();
        jsonWriter.value("quote\"test");
        jsonWriter.endArray();

        // Gson escapes quotes by default
        assertEquals("[\"quote\\\"test\"]", writer.toString());
    }
}
